using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.Events;using UnityEditor.SceneManagement;using TMPro;using EternalSteam.OpenWorld;
public static class PolishHud05{public static string Main(){if(Application.isPlaying||EditorSceneManager.GetActiveScene().isDirty)throw new Exception("Clean Edit required");var setup=EditorSceneManager.GetSceneManagerSetup();try{foreach(var name in new[]{"StartRegionSandbox","OpenWorldSandbox"}){var scene=EditorSceneManager.OpenScene("Assets/EternalSteam/Scene/Tests/"+name+".unity");var h=UnityEngine.Object.FindFirstObjectByType<CanvasWorldHud>();if(!h.Buttons.Any(b=>b.Id=="category-4")){var source=h.Buttons.Single(b=>b.Id=="category-3").View;var button=UnityEngine.Object.Instantiate(source,source.transform.parent);button.name="category-4";((RectTransform)button.transform).anchoredPosition=new Vector2(500,0);var caption=button.GetComponentInChildren<TMP_Text>();caption.name="category-4-caption";caption.text="철도";while(button.onClick.GetPersistentEventCount()>0)UnityEventTools.RemovePersistentListener(button.onClick,0);UnityEventTools.AddStringPersistentListener(button.onClick,h.Execute,"category:4");h.Buttons=h.Buttons.Concat(new[]{new CanvasWorldHud.ButtonBinding{Id="category-4",View=button}}).ToArray();h.Texts=h.Texts.Concat(new[]{new CanvasWorldHud.TextBinding{Id="category-4-caption",View=caption}}).ToArray();h.Layout.Texts=h.Layout.Texts.Concat(new[]{caption}).ToArray();h.Layout.FontSizes=h.Layout.FontSizes.Concat(new[]{18f}).ToArray();h.Layout.CategoryStrip.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal,604);}
h.Layout.EditHeader=(RectTransform)h.Buttons.Single(b=>b.Id=="edit").View.transform;h.Layout.PowerHeader=(RectTransform)h.Buttons.Single(b=>b.Id=="power-fold").View.transform;h.Layout.EditActions=h.Sections.Single(s=>s.Id=="edit-actions").Body.transform as RectTransform;
var existing=h.Layout.Texts.Select((t,i)=>(t,size:h.Layout.FontSizes[i])).ToDictionary(v=>v.t,v=>v.size);h.Layout.Texts=h.GetComponentsInChildren<TMP_Text>(true);h.Layout.FontSizes=h.Layout.Texts.Select(t=>t.transform.IsChildOf(h.Layout.ConstructionBar)?18f:existing.TryGetValue(t,out float size)?size:t.fontSize).ToArray();
foreach(var t in h.Layout.ConstructionBar.GetComponentsInChildren<TMP_Text>(true)){t.enableAutoSizing=false;t.fontSize=18;if(t.GetComponentInParent<UnityEngine.UI.Button>()!=null&&!h.Catalog.Any(c=>t.transform.IsChildOf(c.View.transform))){t.textWrappingMode=TextWrappingModes.NoWrap;t.overflowMode=TextOverflowModes.Ellipsis;}}
h.Layout.Apply(true);EditorUtility.SetDirty(h);EditorUtility.SetDirty(h.Layout);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);}}finally{EditorSceneManager.RestoreSceneManagerSetup(setup);}return "Common railway category and responsive card height saved";}}
